chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"improve-text",title:"Improve with PrivatePen",contexts:["selection"]})});chrome.contextMenus.onClicked.addListener((n,e)=>{n.menuItemId==="improve-text"&&(e!=null&&e.id)&&(chrome.sidePanel.open({windowId:e.windowId}),setTimeout(()=>{chrome.runtime.sendMessage({action:"AnalyzeSelection",text:n.selectionText})},500))});chrome.commands.onCommand.addListener(n=>{n==="open-sidepanel"&&chrome.tabs.query({active:!0,currentWindow:!0},e=>{e[0].id&&chrome.sidePanel.open({windowId:e[0].windowId})})});
